CREATE SCHEMA raw;;
CREATE TABLE raw.flights(flight_id VARCHAR, departure_airport_swedish VARCHAR, departure_airport_english VARCHAR, di_indicator VARCHAR, direction VARCHAR, airport_iata VARCHAR, query_date VARCHAR, fetched_at TIMESTAMP WITH TIME ZONE, flight_leg_identifier__callsign VARCHAR, flight_leg_identifier__flight_id VARCHAR, flight_leg_identifier__flight_departure_date_utc TIMESTAMP WITH TIME ZONE, flight_leg_identifier__departure_airport_iata VARCHAR, flight_leg_identifier__arrival_airport_iata VARCHAR, flight_leg_identifier__departure_airport_icao VARCHAR, flight_leg_identifier__arrival_airport_icao VARCHAR, location_and_status__terminal VARCHAR, location_and_status__flight_leg_status VARCHAR, location_and_status__flight_leg_status_swedish VARCHAR, location_and_status__flight_leg_status_english VARCHAR, arrival_time__scheduled_utc TIMESTAMP WITH TIME ZONE, airline_operator__iata VARCHAR, airline_operator__icao VARCHAR, airline_operator__name VARCHAR, _dlt_load_id VARCHAR NOT NULL, _dlt_id VARCHAR NOT NULL, baggage__baggage_claim_unit VARCHAR, flight_leg_identifier__aircraft_registration VARCHAR, flight_leg_identifier__ssr_code VARCHAR, baggage__first_bag_utc TIMESTAMP WITH TIME ZONE, baggage__last_bag_utc TIMESTAMP WITH TIME ZONE, location_and_status__gate VARCHAR, arrival_time__estimated_utc TIMESTAMP WITH TIME ZONE, arrival_time__actual_utc TIMESTAMP WITH TIME ZONE, arrival_airport_swedish VARCHAR, arrival_airport_english VARCHAR, departure_time__scheduled_utc TIMESTAMP WITH TIME ZONE, check_in__check_in_desk_from BIGINT, check_in__check_in_desk_to BIGINT, check_in__check_in_status VARCHAR, check_in__check_in_status_swedish VARCHAR, check_in__check_in_status_english VARCHAR, location_and_status__gate_action VARCHAR, location_and_status__gate_action_swedish VARCHAR, location_and_status__gate_action_english VARCHAR, location_and_status__gate_open_utc TIMESTAMP WITH TIME ZONE, location_and_status__gate_close_utc TIMESTAMP WITH TIME ZONE, departure_time__actual_utc TIMESTAMP WITH TIME ZONE, departure_time__estimated_utc TIMESTAMP WITH TIME ZONE, baggage__estimated_first_bag_utc TIMESTAMP WITH TIME ZONE);;
CREATE TABLE raw.flights__code_share_data("value" VARCHAR, _dlt_parent_id VARCHAR NOT NULL, _dlt_list_idx BIGINT NOT NULL, _dlt_id VARCHAR NOT NULL);;
CREATE TABLE raw.flights__remarks_english("text" VARCHAR, indicator VARCHAR, _dlt_parent_id VARCHAR NOT NULL, _dlt_list_idx BIGINT NOT NULL, _dlt_id VARCHAR NOT NULL);;
CREATE TABLE raw.flights__remarks_swedish("text" VARCHAR, indicator VARCHAR, _dlt_parent_id VARCHAR NOT NULL, _dlt_list_idx BIGINT NOT NULL, _dlt_id VARCHAR NOT NULL);;
CREATE TABLE raw.flights__via_destinations(airport_iata VARCHAR, airport_swedish VARCHAR, airport_english VARCHAR, _dlt_parent_id VARCHAR NOT NULL, _dlt_list_idx BIGINT NOT NULL, _dlt_id VARCHAR NOT NULL);;
CREATE TABLE raw._dlt_loads(load_id VARCHAR NOT NULL, schema_name VARCHAR, status BIGINT NOT NULL, inserted_at TIMESTAMP WITH TIME ZONE NOT NULL, schema_version_hash VARCHAR);;
CREATE TABLE raw._dlt_pipeline_state("version" BIGINT NOT NULL, engine_version BIGINT NOT NULL, pipeline_name VARCHAR NOT NULL, state VARCHAR NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, version_hash VARCHAR, _dlt_load_id VARCHAR NOT NULL, _dlt_id VARCHAR NOT NULL);;
CREATE TABLE raw._dlt_version("version" BIGINT NOT NULL, engine_version BIGINT NOT NULL, inserted_at TIMESTAMP WITH TIME ZONE NOT NULL, schema_name VARCHAR NOT NULL, version_hash VARCHAR NOT NULL, "schema" VARCHAR NOT NULL);;

